"""Database engine and session management.

Supports both SQLite (default) and PostgreSQL via the DATABASE_URL setting.
PostgreSQL URLs (postgresql:// or postgresql+psycopg2://) get connection pooling
with pre-ping; SQLite uses the default StaticPool-less mode.
"""

from contextlib import contextmanager
from typing import Any

from sqlalchemy import create_engine
from sqlalchemy.orm import DeclarativeBase, sessionmaker
from sqlalchemy.pool import QueuePool

from backend.config import get_settings


class Base(DeclarativeBase):
    """SQLAlchemy declarative base."""


_engine = None
_session_factory = None


def _is_postgresql(url: str) -> bool:
    """Return True if the database URL targets PostgreSQL."""
    return url.startswith("postgresql://") or url.startswith("postgresql+")


def _build_engine_kwargs(url: str, debug: bool) -> dict[str, Any]:
    """Build keyword arguments for ``create_engine`` based on the URL scheme."""
    kwargs: dict[str, Any] = {"echo": debug}
    if _is_postgresql(url):
        kwargs.update(
            poolclass=QueuePool,
            pool_size=5,
            max_overflow=10,
            pool_pre_ping=True,
            pool_recycle=300,
        )
    return kwargs


def create_db_engine():
    """Create a new SQLAlchemy engine from the current settings.

    Uses a connection pool for PostgreSQL and plain mode for SQLite so that
    the default ``sqlite:///./data/elephant_rock.db`` works without extra deps.
    """
    settings = get_settings()
    kwargs = _build_engine_kwargs(settings.database_url, settings.debug)
    return create_engine(settings.database_url, **kwargs)


def _get_engine():
    global _engine
    if _engine is None:
        _engine = create_db_engine()
    return _engine


def _get_session_factory():
    global _session_factory
    if _session_factory is None:
        _session_factory = sessionmaker(bind=_get_engine(), expire_on_commit=False)
    return _session_factory


def create_session_factory():
    return _get_session_factory()


def init_db():
    """Create all tables."""
    Base.metadata.create_all(_get_engine())


@contextmanager
def get_session():
    """Provide a transactional scope around a series of operations."""
    session = _get_session_factory()()
    try:
        yield session
    except Exception:
        session.rollback()
        raise
    finally:
        session.close()

"""CRUD operations for the metadata database."""

import json
from collections.abc import Sequence

from sqlalchemy import select, func, case, desc, asc
from sqlalchemy.orm import Session

from backend.db.models import Idea, Paper, PipelineRun, Proposal, ResearchGapDB

# --- Papers ---


def create_paper(session: Session, **kwargs) -> Paper:
    paper = Paper(**kwargs)
    session.add(paper)
    session.commit()
    session.refresh(paper)
    return paper


def get_paper(session: Session, paper_id: int) -> Paper | None:
    return session.get(Paper, paper_id)


def get_paper_by_source_id(session: Session, source_id: str) -> Paper | None:
    return session.execute(select(Paper).where(Paper.source_id == source_id)).scalar_one_or_none()


def list_papers(session: Session, limit: int = 50, offset: int = 0) -> Sequence[Paper]:
    return (
        session.execute(select(Paper).order_by(Paper.id.desc()).limit(limit).offset(offset))
        .scalars()
        .all()
    )


# --- Ideas ---


def create_idea(session: Session, **kwargs) -> Idea:
    idea = Idea(**kwargs)
    session.add(idea)
    session.commit()
    session.refresh(idea)
    return idea


def get_idea(session: Session, idea_id: int) -> Idea | None:
    return session.get(Idea, idea_id)


def count_ideas(
    session: Session,
    domain: str | None = None,
    min_score: float | None = None,
    search: str | None = None,
) -> int:
    stmt = select(func.count()).select_from(Idea)
    if domain is not None:
        stmt = stmt.where(Idea.domain == domain)
    if min_score is not None:
        stmt = stmt.where(Idea.overall_score >= min_score)
    if search is not None:
        stmt = stmt.where(Idea.title.ilike(f"%{search}%"))
    return session.execute(stmt).scalar_one()


VALID_SORT_COLUMNS = {
    "score": Idea.overall_score,
    "novelty": Idea.novelty_score,
    "feasibility": Idea.feasibility_score,
    "date": Idea.created_at,
}


def list_ideas(
    session: Session,
    limit: int = 50,
    offset: int = 0,
    domain: str | None = None,
    min_score: float | None = None,
    search: str | None = None,
    sort_by: str | None = None,
    sort_order: str = "desc",
) -> Sequence[Idea]:
    stmt = select(Idea)

    # Filters
    if domain is not None:
        stmt = stmt.where(Idea.domain == domain)
    if min_score is not None:
        stmt = stmt.where(Idea.overall_score >= min_score)
    if search is not None:
        stmt = stmt.where(Idea.title.ilike(f"%{search}%"))

    # Sorting
    sort_col = VALID_SORT_COLUMNS.get(sort_by) if sort_by else None
    if sort_col is not None:
        # Nulls last: use CASE to push NULLs to the end
        nulls_last_expr = case((sort_col.is_(None), 1), else_=0)
        direction = desc if sort_order == "desc" else asc
        stmt = stmt.order_by(nulls_last_expr, direction(sort_col))
    else:
        stmt = stmt.order_by(Idea.id.desc())

    stmt = stmt.limit(limit).offset(offset)
    return session.execute(stmt).scalars().all()


def get_ideas_for_run(session: Session, run_id: int) -> Sequence[Idea]:
    """Return all ideas linked to a pipeline run via pipeline_run_id FK."""
    return (
        session.execute(
            select(Idea).where(Idea.pipeline_run_id == run_id).order_by(Idea.id.asc())
        )
        .scalars()
        .all()
    )


def count_ideas_for_run(session: Session, run_id: int) -> int:
    """Return the total count of ideas linked to a pipeline run."""
    return session.execute(
        select(func.count())
        .select_from(Idea)
        .where(Idea.pipeline_run_id == run_id)
    ).scalar_one()


def update_idea_scores(
    session: Session,
    idea_id: int,
    novelty_score: float | None = None,
    feasibility_score: float | None = None,
    novelty_report: str | None = None,
    feasibility_report: str | None = None,
) -> Idea | None:
    idea = session.get(Idea, idea_id)
    if not idea:
        return None
    if novelty_score is not None:
        idea.novelty_score = novelty_score
    if feasibility_score is not None:
        idea.feasibility_score = feasibility_score
    if novelty_report is not None:
        idea.novelty_report = novelty_report
    if feasibility_report is not None:
        idea.feasibility_report = feasibility_report
    if idea.novelty_score is not None and idea.feasibility_score is not None:
        normalized_feasibility = idea.feasibility_score / 10.0
        idea.overall_score = (idea.novelty_score + normalized_feasibility) / 2
    session.commit()
    session.refresh(idea)
    return idea


def update_idea_feedback(
    session: Session,
    idea_id: int,
    rating: int,
    notes: str | None = None,
) -> Idea | None:
    idea = session.get(Idea, idea_id)
    if not idea:
        return None
    idea.user_rating = rating
    idea.user_notes = notes
    session.commit()
    session.refresh(idea)
    return idea


# --- Proposals ---


def create_proposal(session: Session, idea_id: int, content_md: str, **kwargs) -> Proposal:
    proposal = Proposal(idea_id=idea_id, content_md=content_md, **kwargs)
    session.add(proposal)
    session.commit()
    session.refresh(proposal)
    return proposal


def get_proposal_by_idea(session: Session, idea_id: int) -> Proposal | None:
    return session.execute(select(Proposal).where(Proposal.idea_id == idea_id)).scalar_one_or_none()


# --- Pipeline Runs ---


def count_pipeline_runs(
    session: Session,
    session_id: str | None = None,
) -> int:
    stmt = select(func.count()).select_from(PipelineRun)
    if session_id is not None:
        stmt = stmt.where(PipelineRun.session_id == session_id)
    return session.execute(stmt).scalar_one()


def list_pipeline_runs(
    session: Session,
    limit: int = 20,
    offset: int = 0,
    session_id: str | None = None,
) -> Sequence[PipelineRun]:
    stmt = select(PipelineRun)
    if session_id is not None:
        stmt = stmt.where(PipelineRun.session_id == session_id)
    stmt = stmt.order_by(PipelineRun.id.desc()).limit(limit).offset(offset)
    return session.execute(stmt).scalars().all()


def list_session_ids(session: Session) -> list[dict]:
    """Return unique session_id values with run count and latest run timestamp.

    Returns list of dicts: [{session_id, run_count, latest_run_at}].
    Only includes runs where session_id is not NULL.
    """
    stmt = (
        select(
            PipelineRun.session_id,
            func.count().label("run_count"),
            func.max(PipelineRun.created_at).label("latest_run_at"),
        )
        .where(PipelineRun.session_id.isnot(None))
        .group_by(PipelineRun.session_id)
        .order_by(func.max(PipelineRun.created_at).desc())
    )
    rows = session.execute(stmt).all()
    return [
        {
            "session_id": row.session_id,
            "run_count": row.run_count,
            "latest_run_at": str(row.latest_run_at),
        }
        for row in rows
    ]


def create_pipeline_run(session: Session, **kwargs) -> PipelineRun:
    run = PipelineRun(**kwargs)
    session.add(run)
    session.commit()
    session.refresh(run)
    return run


def get_pipeline_run(session: Session, run_id: int) -> PipelineRun | None:
    return session.get(PipelineRun, run_id)


def update_pipeline_run(
    session: Session,
    run_id: int,
    status: str | None = None,
    current_stage: str | None = None,
    error_message: str | None = None,
) -> PipelineRun | None:
    run = session.get(PipelineRun, run_id)
    if not run:
        return None
    if status is not None:
        run.status = status
    if current_stage is not None:
        run.current_stage = current_stage
        completed = json.loads(run.stages_completed)
        if current_stage not in completed:
            completed.append(current_stage)
            run.stages_completed = json.dumps(completed)
    if error_message is not None:
        run.error_message = error_message
    from datetime import datetime, timezone

    if status == "completed":
        run.completed_at = datetime.now(timezone.utc)
    session.commit()
    session.refresh(run)
    return run


# --- Research Gaps ---


def create_gap(session: Session, **kwargs) -> ResearchGapDB:
    gap = ResearchGapDB(**kwargs)
    session.add(gap)
    session.commit()
    session.refresh(gap)
    return gap


def get_gap(session: Session, gap_id: int) -> ResearchGapDB | None:
    return session.get(ResearchGapDB, gap_id)


def list_gaps_by_run(session: Session, run_id: int) -> Sequence[ResearchGapDB]:
    return (
        session.execute(
            select(ResearchGapDB)
            .where(ResearchGapDB.pipeline_run_id == run_id)
            .order_by(ResearchGapDB.confidence.desc())
        )
        .scalars()
        .all()
    )


def count_gaps_by_run(session: Session, run_id: int) -> int:
    return session.execute(
        select(func.count())
        .select_from(ResearchGapDB)
        .where(ResearchGapDB.pipeline_run_id == run_id)
    ).scalar_one()


# --- Research Gaps: Search / Filter / Sort (BATCH-39) ---

VALID_GAP_SORT_COLUMNS = {
    "confidence": ResearchGapDB.confidence,
    "date": ResearchGapDB.created_at,
    "type": ResearchGapDB.gap_type,
}

VALID_GAP_TYPES = {"methodological", "empirical", "theoretical", "cross-domain"}


def count_search_gaps(
    session: Session,
    run_id: int | None = None,
    search: str | None = None,
    gap_type: str | None = None,
    min_confidence: float | None = None,
) -> int:
    """Count gaps matching filter criteria (BATCH-39)."""
    stmt = select(func.count()).select_from(ResearchGapDB)
    if run_id is not None:
        stmt = stmt.where(ResearchGapDB.pipeline_run_id == run_id)
    if search is not None:
        stmt = stmt.where(
            (ResearchGapDB.title.ilike(f"%{search}%"))
            | (ResearchGapDB.description.ilike(f"%{search}%"))
        )
    if gap_type is not None and gap_type in VALID_GAP_TYPES:
        stmt = stmt.where(ResearchGapDB.gap_type == gap_type)
    if min_confidence is not None:
        stmt = stmt.where(ResearchGapDB.confidence >= min_confidence)
    return session.execute(stmt).scalar_one()


def search_gaps(
    session: Session,
    run_id: int | None = None,
    search: str | None = None,
    gap_type: str | None = None,
    min_confidence: float | None = None,
    sort_by: str | None = None,
    sort_order: str = "desc",
    limit: int = 20,
    offset: int = 0,
) -> Sequence[ResearchGapDB]:
    """Return gaps matching filter/sort criteria (BATCH-39).

    Args:
        session: SQLAlchemy session.
        run_id: Optional pipeline run ID filter.
        search: Case-insensitive substring match on title and description.
        gap_type: Exact match filter (validated against VALID_GAP_TYPES).
        min_confidence: Minimum confidence threshold.
        sort_by: Column to sort by (validated against VALID_GAP_SORT_COLUMNS).
        sort_order: "asc" or "desc" (default: "desc").
        limit: Max results.
        offset: Pagination offset.

    Returns:
        Sequence of matching ResearchGapDB objects.
    """
    stmt = select(ResearchGapDB)

    # Filters
    if run_id is not None:
        stmt = stmt.where(ResearchGapDB.pipeline_run_id == run_id)
    if search is not None:
        stmt = stmt.where(
            (ResearchGapDB.title.ilike(f"%{search}%"))
            | (ResearchGapDB.description.ilike(f"%{search}%"))
        )
    if gap_type is not None and gap_type in VALID_GAP_TYPES:
        stmt = stmt.where(ResearchGapDB.gap_type == gap_type)
    if min_confidence is not None:
        stmt = stmt.where(ResearchGapDB.confidence >= min_confidence)

    # Sorting (AR-01: whitelist — invalid values ignored)
    sort_col = VALID_GAP_SORT_COLUMNS.get(sort_by) if sort_by else None
    if sort_col is not None:
        direction = desc if sort_order == "desc" else asc
        stmt = stmt.order_by(direction(sort_col))
    else:
        stmt = stmt.order_by(ResearchGapDB.confidence.desc())

    stmt = stmt.limit(limit).offset(offset)
    return session.execute(stmt).scalars().all()


def count_ideas_for_gap(session: Session, gap_title: str) -> int:
    """Count ideas whose source_gap_ids JSON contains the given gap title.

    Uses parameterized LIKE query (HB-01) — the gap title is passed as a
    bound parameter, never interpolated into SQL.
    """
    stmt = (
        select(func.count())
        .select_from(Idea)
        .where(Idea.source_gap_ids.isnot(None))
        .where(Idea.source_gap_ids.ilike(f"%{gap_title}%"))
    )
    return session.execute(stmt).scalar_one()


def update_gap_feedback(session: Session, gap_id: int, rating: int, notes: str | None = None) -> ResearchGapDB | None:
    """Update user rating and notes for a gap (BATCH-41)."""
    gap = session.get(ResearchGapDB, gap_id)
    if not gap:
        return None
    gap.user_rating = rating
    if notes is not None:
        gap.user_notes = notes
    session.commit()
    session.refresh(gap)
    return gap


def update_gap_status(session: Session, gap_id: int, new_status: str) -> ResearchGapDB | None:
    """Update gap lifecycle status with forward-only validation (BATCH-41)."""
    VALID_TRANSITIONS = {
        "identified": "investigating",
        "investigating": "addressed",
    }
    gap = session.get(ResearchGapDB, gap_id)
    if not gap:
        return None
    current = gap.status or "identified"
    if new_status == current:
        return gap  # No-op
    expected_next = VALID_TRANSITIONS.get(current)
    if expected_next != new_status:
        return None  # Invalid transition — caller returns 422
    gap.status = new_status
    session.commit()
    session.refresh(gap)
    return gap


def find_gap_by_hash(session: Session, content_hash: str) -> ResearchGapDB | None:
    """Find a gap by content_hash for deduplication (BATCH-42)."""
    return session.execute(
        select(ResearchGapDB).where(ResearchGapDB.content_hash == content_hash).limit(1)
    ).scalar_one_or_none()


def list_canonical_gaps(session: Session, limit: int = 100) -> list[ResearchGapDB]:
    """List deduplicated gaps (one per unique content_hash, BATCH-42)."""
    from sqlalchemy import distinct
    # Get unique hashes and pick the first gap for each
    subq = (
        select(ResearchGapDB.id, ResearchGapDB.content_hash)
        .where(ResearchGapDB.content_hash.isnot(None))
        .distinct(ResearchGapDB.content_hash)
        .order_by(ResearchGapDB.content_hash, ResearchGapDB.id)
        .subquery()
    )
    return session.execute(
        select(ResearchGapDB).join(subq, ResearchGapDB.id == subq.c.id)
        .order_by(ResearchGapDB.confidence.desc())
        .limit(limit)
    ).scalars().all()

import { useQuery } from "@tanstack/react-query";
import { useNavigate, useParams } from "react-router-dom";
import { getRunDetail, getRunIdeas } from "@/api/pipeline";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { PIPELINE_STAGES } from "@/lib/constants";
import { cn } from "@/lib/utils";
import {
  ArrowLeft,
  CheckCircle2,
  Circle,
  Loader2,
  AlertTriangle,
  Play,
  Lightbulb,
  Clock,
} from "lucide-react";
import type { PipelineRunDetail, IdeaSummary } from "@/api/types";

const statusColors: Record<string, string> = {
  pending: "bg-yellow-100 text-yellow-800",
  running: "bg-blue-100 text-blue-800",
  completed: "bg-green-100 text-green-800",
  failed: "bg-red-100 text-red-800",
};

export default function RunDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const runId = Number(id);

  const {
    data: run,
    isLoading: runLoading,
    error: runError,
  } = useQuery({
    queryKey: ["run", runId],
    queryFn: () => getRunDetail(runId),
    enabled: !isNaN(runId),
  });

  const { data: ideasData } = useQuery({
    queryKey: ["run", runId, "ideas"],
    queryFn: () => getRunIdeas(runId),
    enabled: !isNaN(runId) && !!run,
  });

  if (runError) {
    return (
      <div className="space-y-6">
        <Button variant="ghost" onClick={() => navigate("/")} data-testid="back-btn">
          <ArrowLeft className="h-4 w-4 mr-2" />
          Back to Dashboard
        </Button>
        <Card>
          <CardContent className="p-8 text-center" data-testid="run-not-found">
            <AlertTriangle className="h-8 w-8 mx-auto mb-2 text-destructive" />
            <p className="text-lg font-medium">Run not found</p>
            <p className="text-sm text-muted-foreground mt-1">
              No pipeline run found with ID {id}.
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (runLoading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-64 w-full" />
      </div>
    );
  }

  if (!run) {
    return (
      <div className="space-y-6">
        <Button variant="ghost" onClick={() => navigate("/")} data-testid="back-btn">
          <ArrowLeft className="h-4 w-4 mr-2" />
          Back to Dashboard
        </Button>
        <Card>
          <CardContent className="p-8 text-center" data-testid="run-not-found">
            <AlertTriangle className="h-8 w-8 mx-auto mb-2 text-destructive" />
            <p className="text-lg font-medium">Run not found</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  const ideas = ideasData?.ideas ?? [];

  return (
    <div className="space-y-6" data-testid="run-detail">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <Button variant="ghost" onClick={() => navigate("/")} data-testid="back-btn">
            <ArrowLeft className="h-4 w-4 mr-2" />
            Back
          </Button>
          <div>
            <h1 className="text-2xl font-bold tracking-tight" data-testid="run-title">
              Run #{run.id}
            </h1>
            <p className="text-sm text-muted-foreground">{run.domain}</p>
          </div>
        </div>
        <Badge className={cn("text-sm", statusColors[run.status])} data-testid="run-status">
          {run.status}
        </Badge>
      </div>

      {/* Metadata */}
      <Card data-testid="run-metadata">
        <CardHeader>
          <CardTitle className="text-sm font-medium">Run Metadata</CardTitle>
        </CardHeader>
        <CardContent>
          <dl className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
            <div>
              <dt className="text-muted-foreground">ID</dt>
              <dd className="font-medium">{run.id}</dd>
            </div>
            <div>
              <dt className="text-muted-foreground">Domain</dt>
              <dd className="font-medium">{run.domain}</dd>
            </div>
            <div>
              <dt className="text-muted-foreground">Created</dt>
              <dd className="font-medium" data-testid="run-created-at">
                {new Date(run.created_at).toLocaleString()}
              </dd>
            </div>
            <div>
              <dt className="text-muted-foreground">Completed</dt>
              <dd className="font-medium" data-testid="run-completed-at">
                {run.completed_at
                  ? new Date(run.completed_at).toLocaleString()
                  : "—"}
              </dd>
            </div>
          </dl>
        </CardContent>
      </Card>

      {/* Stages Timeline */}
      <Card data-testid="stages-timeline">
        <CardHeader>
          <CardTitle className="text-sm font-medium">Stages</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {PIPELINE_STAGES.map((stage) => {
              const isCompleted = run.stages_completed.includes(stage.key);
              const isCurrent = run.current_stage === stage.key;
              return (
                <div key={stage.key} className="flex items-center gap-3">
                  {isCompleted ? (
                    <CheckCircle2 className="h-5 w-5 text-green-600 flex-shrink-0" />
                  ) : isCurrent ? (
                    <Loader2 className="h-5 w-5 text-blue-600 animate-spin flex-shrink-0" />
                  ) : (
                    <Circle className="h-5 w-5 text-muted-foreground flex-shrink-0" />
                  )}
                  <span
                    className={cn(
                      "text-sm",
                      isCompleted ? "text-foreground font-medium" : "text-muted-foreground",
                    )}
                  >
                    {stage.label}
                  </span>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* Error Message (for failed runs) */}
      {run.status === "failed" && run.error_message && (
        <Card className="border-destructive" data-testid="error-message">
          <CardContent className="p-4">
            <div className="flex items-start gap-3">
              <AlertTriangle className="h-5 w-5 text-destructive flex-shrink-0 mt-0.5" />
              <div>
                <p className="text-sm font-medium text-destructive">Pipeline Failed</p>
                <p className="text-sm text-muted-foreground mt-1">{run.error_message}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Resume Button (for failed runs) */}
      {run.status === "failed" && (
        <Button data-testid="resume-btn" className="w-full sm:w-auto">
          <Play className="h-4 w-4 mr-2" />
          Resume Pipeline
        </Button>
      )}

      {/* Generated Ideas */}
      <Card data-testid="ideas-list">
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm font-medium">Generated Ideas</CardTitle>
            {ideas.length > 0 && (
              <span className="text-sm text-muted-foreground flex items-center gap-1">
                <Lightbulb className="h-4 w-4" />
                {ideas.length} idea{ideas.length !== 1 ? "s" : ""}
              </span>
            )}
          </div>
        </CardHeader>
        <CardContent>
          {ideas.length === 0 ? (
            <p className="text-sm text-muted-foreground">No ideas generated in this run.</p>
          ) : (
            <div className="space-y-3">
              {ideas.map((idea: IdeaSummary) => (
                <Card
                  key={idea.id}
                  className="cursor-pointer hover:bg-accent/50 transition-colors"
                  onClick={() => navigate(`/ideas/${idea.id}`)}
                >
                  <CardContent className="p-4">
                    <div className="flex items-center justify-between">
                      <div className="min-w-0 flex-1">
                        <p className="text-sm font-medium line-clamp-1">{idea.title}</p>
                        <p className="text-xs text-muted-foreground">{idea.domain}</p>
                      </div>
                      {idea.overall_score !== null && (
                        <Badge variant="secondary" className="ml-2">
                          {(idea.overall_score * 100).toFixed(0)}%
                        </Badge>
                      )}
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Duration info */}
      {run.completed_at && run.created_at && (
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Clock className="h-4 w-4" />
              <span>
                Duration:{" "}
                {(
                  (new Date(run.completed_at).getTime() -
                    new Date(run.created_at).getTime()) /
                  1000
                ).toFixed(1)}{" "}
                seconds
              </span>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useQuery } from "@tanstack/react-query";
import { lazy, Suspense } from "react";
import { listRuns } from "@/api/pipeline";
import { getSystemStatus } from "@/api/status";
import { listIdeas } from "@/api/ideas";
import { RunCard } from "@/components/pipeline/run-card";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { useNavigate } from "react-router-dom";
import { Activity, Lightbulb, FlaskConical, Server } from "lucide-react";

const ScoreDistributionChart = lazy(() =>
  import("@/components/charts/score-distribution").then((m) => ({ default: m.ScoreDistributionChart })),
);
const DomainBreakdownChart = lazy(() =>
  import("@/components/charts/domain-breakdown").then((m) => ({ default: m.DomainBreakdownChart })),
);
const RunStatusChart = lazy(() =>
  import("@/components/charts/run-status-chart").then((m) => ({ default: m.RunStatusChart })),
);

export default function Dashboard() {
  const navigate = useNavigate();

  const { data: status, isLoading: statusLoading } = useQuery({
    queryKey: ["status"],
    queryFn: getSystemStatus,
  });

  const { data: runsData, isLoading: runsLoading } = useQuery({
    queryKey: ["runs", { limit: 5 }],
    queryFn: () => listRuns({ limit: 5 }),
  });

  const { data: ideasData, isLoading: ideasLoading } = useQuery({
    queryKey: ["ideas", { limit: 5 }],
    queryFn: () => listIdeas({ limit: 5 }),
  });

  const { data: chartIdeas } = useQuery({
    queryKey: ["ideas", { limit: 200 }],
    queryFn: () => listIdeas({ limit: 200 }),
  });

  const { data: chartRuns } = useQuery({
    queryKey: ["runs", { limit: 50 }],
    queryFn: () => listRuns({ limit: 50 }),
  });

  const hasChartData =
    (chartIdeas?.ideas.length ?? 0) > 0 || (chartRuns?.runs.length ?? 0) > 0;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Dashboard</h1>
        <p className="text-muted-foreground">Overview of your research pipeline.</p>
      </div>

      <div className="dashboard-grid grid gap-4 md:grid-cols-3">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">Total Runs</CardTitle>
            <Activity className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            {runsLoading ? (
              <Skeleton className="h-8 w-16" />
            ) : (
              <span className="text-2xl font-bold">{runsData?.total ?? 0}</span>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">Total Ideas</CardTitle>
            <Lightbulb className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            {ideasLoading ? (
              <Skeleton className="h-8 w-16" />
            ) : (
              <span className="text-2xl font-bold">{ideasData?.total ?? 0}</span>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">System</CardTitle>
            <Server className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            {statusLoading ? (
              <Skeleton className="h-8 w-24" />
            ) : (
              <div>
                <span className="text-2xl font-bold">{status?.app_name ?? "—"}</span>
                <p className="text-xs text-muted-foreground">v{status?.version ?? "—"}</p>
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {hasChartData && (
        <Suspense fallback={<Skeleton className="h-64 w-full" />}>
          <div className="space-y-4">
            <h2 className="text-lg font-semibold">Analytics</h2>
            <div className="grid gap-4 md:grid-cols-2">
              <Card>
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Score Distribution</CardTitle>
                </CardHeader>
                <CardContent>
                  <ScoreDistributionChart ideas={chartIdeas?.ideas ?? []} />
                </CardContent>
              </Card>
              <Card>
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Run Status</CardTitle>
                </CardHeader>
                <CardContent>
                  <RunStatusChart runs={chartRuns?.runs ?? []} />
                </CardContent>
              </Card>
            </div>
            <Card>
              <CardHeader>
                <CardTitle className="text-sm font-medium">Ideas by Domain</CardTitle>
              </CardHeader>
              <CardContent>
                <DomainBreakdownChart ideas={chartIdeas?.ideas ?? []} />
              </CardContent>
            </Card>
          </div>
        </Suspense>
      )}

      <div className="grid gap-6 md:grid-cols-2">
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-semibold">Recent Runs</h2>
            <button
              onClick={() => navigate("/pipeline/new")}
              className="text-sm text-primary hover:underline"
            >
              New run
            </button>
          </div>
          {runsLoading ? (
            <div className="space-y-2">
              {Array.from({ length: 3 }).map((_, i) => (
                <Skeleton key={i} className="h-16 w-full" />
